import rclpy
from rclpy.node import Node
from rclpy.time import Time
from tf2_ros import TransformException
from tf2_ros.buffer import Buffer
from tf2_ros.transform_listener import TransformListener


def ensure_tf_listener(state, node):
    if "tf_buffer" not in state:
        state["tf_buffer"] = Buffer()
        state["tf_listener"] = TransformListener(state["tf_buffer"], node)
    return state["tf_buffer"]


def _field(value, name, default=None):
    attr = getattr(value, name, default)
    if callable(attr):
        try:
            return attr()
        except TypeError:
            return attr
    return attr


def lookup_with_tf2_ros(state, node, parent, child):
    buffer = ensure_tf_listener(state, node)
    try:
        transform = buffer.lookup_transform(parent, child, Time())
        trans = _field(_field(transform, "transform"), "translation")
        return (
            float(_field(trans, "x", 0.0)),
            float(_field(trans, "y", 0.0)),
            float(_field(trans, "z", 0.0)),
        )
    except TransformException as exc:
        state["last_tf2_ros_error"] = str(exc)
        return None
